  function regionFam(name) {
    if (name === 'warp') return 'edge';
    if (/^c\.kb\d\.math$/.test(name)) return 'math';
    if (/^c\.kb\d\.wait$/.test(name) || name === 'c.bscale_bar' || /^c\.epi\.(bar\d|store_wait)$/.test(name)) return 'cwait';
    if (/^c\.epi\./.test(name)) return 'epi';
    if (name === 'c.sched' || name === 'c.bscale_load') return 'sched';
    if (/^p\.kb\d\.wait$/.test(name)) return 'pwait';
    if (/^p\.kb\d\.issue$/.test(name)) return 'pissue';
    if (name === 'p.sched' || name === 'p.drain') return 'pmisc';
    return 'edge';
  }
